// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(address newOwner) public {
        // Ensure newOwner can be any address including zero
        vm.assume(newOwner != address(0));

        // Add a reward token to satisfy the preconditions for the property
        vm.prank(c.owner());
        c.addReward(address(0x1));

        // Now test: after addReward, transfer to zero address should revert in original but not in mutant
        // Property: transferOwnership to zero address NEVER succeeds
        // Try transferring to zero address
        vm.prank(c.owner());
        (bool success, ) = address(c).call(abi.encodeWithSignature("transferOwnership(address)", address(0)));

        // General rule: after addReward, calling transferOwnership(0) must revert
        assertTrue(!success, "transferOwnership(0) should revert");
    }
}

